import duckdb
import pandas as pd
from pandas.testing import assert_frame_equal

def verify_elt_pipeline(conn, expected_tables: dict) -> float:
    passed = 0
    for table_name, expected_df in expected_tables.items():
        try:
            # 1. Fetch the actual table generated by the model in DuckDB
            actual_df = conn.execute(f"SELECT * FROM {table_name}").df()
            
            # 2. Sort both datasets so row order doesn't cause a false failure
            actual_sorted = actual_df.sort_values(by=list(actual_df.columns)).reset_index(drop=True)
            expected_sorted = expected_df.sort_values(by=list(expected_df.columns)).reset_index(drop=True)
            
            # 3. Compare values while ignoring minor type differences (e.g., int32 vs int64)
            assert_frame_equal(actual_sorted, expected_sorted, check_dtype=False)
            passed += 1
        except Exception:
            continue
            
    # 4. Return a score between 0.0 (failed) and 1.0 (perfect match)
    return passed / len(expected_tables) if expected_tables else 0.0